from pathlib import Path
import json,hashlib,re
from datetime import datetime,timezone,timedelta
import pyarrow.parquet as pq
root=Path.cwd(); out=root/"reports/research/510300_dr007_amount_shared_local_source_probe_v1"
freeze=json.loads((out/"第二层原来源导航.json").read_text(encoding="utf-8"))["freeze"]
targets=[v for v in freeze["sources"] if "/dr007_" in v["path"]]
def scrub(value):
 if isinstance(value,dict):
  return {k:("[凭据字段未输出]" if re.search(r"token|password|secret|authorization|api[_-]?key|headers|credential",k,re.I) else scrub(v)) for k,v in value.items()}
 if isinstance(value,list): return [scrub(v) for v in value]
 return value
records=[]
for row in targets:
 f=root/row["path"]
 actual=hashlib.sha256(f.read_bytes()).hexdigest()
 rec={"path":row["path"],"exists":f.exists(),"sha256":actual,"matches_technical_frozen_hash":actual==row["sha256"]}
 if f.suffix==".parquet":
  pf=pq.ParquetFile(f)
  rec.update({"rows":pf.metadata.num_rows,"schema":str(pf.schema_arrow),"columns":pf.schema_arrow.names,"amount_column_present":"amount" in pf.schema_arrow.names})
 elif f.suffix==".json":
  rec["metadata"]=scrub(json.loads(f.read_text(encoding="utf-8-sig")))
 records.append(rec)
record={"at":datetime.now(timezone(timedelta(hours=8))).isoformat(),"direct_original_targets":records,"schema_inspections":1,"new_network_requests":0,"raw_amount_rows_read":0,"credential_outputs":0}
(out/"实际主源schema与原收件导航.json").write_text(json.dumps(record,ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
print(json.dumps(record,ensure_ascii=False))
